    Bug 2020623 - Increase selector specificity so -moz-context-properties are overridden for menu item icons. r=arschmitz

    Without this change, the stroke of icons in menupopups is not set and will thus default to black.

    Differential Revision: https://phabricator.services.mozilla.com/D285707

diff --git a/mail/themes/osx/mail/messenger.css b/mail/themes/osx/mail/messenger.css
index 72f19eb57fd..41011c9cdae 100644
--- a/mail/themes/osx/mail/messenger.css
+++ b/mail/themes/osx/mail/messenger.css
@@ -29,8 +29,8 @@
   }
 }

-#mail-menubar,
-#mailContext {
+#mail-menubar .menu-icon,
+#mailContext .menu-icon {
   -moz-context-properties: fill, stroke;
   fill: color-mix(in srgb, currentColor 20%, transparent);
   stroke: currentColor;
